@Component({
    selector: 'app-login',
    templateUrl: './login.component.html',
    styleUrls: ['./login.component.scss'],
    imports:[MaterialModule]
})
export class LoginComponent implements OnInit, OnDestroy {
  private authService = inject(AuthService);
  private sessionService = inject(SessionService);
  private router = inject(Router);
  private fb = inject(FormBuilder);
  public hide = true;
  public onError = false;
  private destroy$!: Subject<boolean>;

  public form = this.fb.group({
    email: [
      '',
      [
        Validators.required,
        Validators.email
      ]
    ],
    password: [
      '',
      [
        Validators.required
      ]
    ]
  });
  
  constructor() { }

  ngOnDestroy(): void {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  ngOnInit(): void {
    this.destroy$ = new Subject<boolean>();
  }

  public submit(): void {
    const loginRequest = this.form.value as LoginRequest;
    this.authService.login(loginRequest).pipe(takeUntil(this.destroy$)).subscribe({
      next: (response: SessionInformation) => {
        this.sessionService.logIn(response);
        this.router.navigate(['/feed/article']);
      },
      error: error => this.onError = true,
    });
  }

  public back(): void{
    this.router.navigate(['']);
  }
}

import { AbstractControl, MinLengthValidator, ValidationErrors, ValidatorFn } from '@angular/forms';

export function authValidator(): ValidatorFn {
    return (ctrl: AbstractControl): null | ValidationErrors => {

        const HasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]+/.test(ctrl.value);

        const hasUpperCase = /[A-Z]+/.test(ctrl.value);

        const hasLowerCase = /[a-z]+/.test(ctrl.value);

        const hasNumeric = /[0-9]+/.test(ctrl.value);

        const passwordValid = HasSpecialChar && hasUpperCase && hasLowerCase && hasNumeric;

        if(passwordValid){
            return null;
        } else {
           return { validValidator: ctrl.value };
        }
    };
}

export function mePassValidator(): ValidatorFn {
    return (ctrl: AbstractControl): null | ValidationErrors => {

        const HasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]+/.test(ctrl.value);

        const hasUpperCase = /[A-Z]+/.test(ctrl.value);

        const hasLowerCase = /[a-z]+/.test(ctrl.value);

        const hasNumeric = /[0-9]+/.test(ctrl.value);

        const passwordValid = HasSpecialChar && hasUpperCase && hasLowerCase && hasNumeric;

        if(passwordValid || ctrl.value==""){
            return null;
        } else {
           return { mePassValidator: ctrl.value };
        }
    };
}

import { Component, inject, OnInit } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { Subject, takeUntil } from 'rxjs';
import { RegisterRequest } from 'src/app/core/models/registerRequest.interface';
import { AuthService } from 'src/app/core/services/auth.service';
import { authValidator } from 'src/app/core/validators/valid.validator';
import { MaterialModule } from 'src/app/shared/material.module';

@Component({
    selector: 'app-register',
    templateUrl: './register.component.html',
    styleUrls: ['./register.component.scss'],
    imports:[MaterialModule]
})
export class RegisterComponent implements OnInit {
  private authService = inject(AuthService);
  private router = inject(Router);
  private destroy$!: Subject<boolean>;
  public onError = false;
  private fb = inject(FormBuilder);
  public hide = true;

  public form = this.fb.group({
    username: [
      '',
      [
        Validators.required,
      ]
    ],
    email: [
      '',
      [
        Validators.required,
        Validators.email,
      ]
    ],
    password: [
      '',
      [
        Validators.required,
        Validators.minLength(8),
        authValidator(),
      ]
    ]
  });
  constructor() { }
  
  ngOnDestroy(): void {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  ngOnInit(): void {
    this.destroy$ = new Subject<boolean>();
  }

  public submit(): void {
    const registerRequest = this.form.value as RegisterRequest;
    this.authService.register(registerRequest).pipe(takeUntil(this.destroy$)).subscribe({
        next: (_: void) => this.router.navigate(['/login']),
        error: _ => this.onError = true,
      }
    );
  }

  public back(): void{
    this.router.navigate(['']);
  }

}

