  private router = inject(Router);
  private fb = inject(FormBuilder);
  private destroy$!: Subject<boolean>;
  public theme$!: Observable<Theme[]>;
  public themeForm!: Theme;
  private subscriptionService = inject(SubscriptionService);
  
  public articleForm = this.fb.group({
    title: [
      '',
      [
        Validators.required
      ]
    ],
    theme: [
      this.themeForm,
      [
        Validators.required
      ]
    ],
    content: [
      '',
      [
        Validators.required,
        Validators.max(254)
      ]
    ]
  });

  ngOnInit(): void {
    this.destroy$ = new Subject<boolean>();
    this.theme$ = this.subscriptionService.getByUser();
  }

  ngOnDestroy(): void {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  submit():void {
    const articleRequest = this.articleForm.value as ArticlePayload;
    this.articleService
      .create(articleRequest)
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        this.backtoArticleList()});
  }

  backtoArticleList():void{
    this.router.navigate(['feed/article']);
  }
}

import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'customDatePipe'
})
export class CustomDatePipePipe implements PipeTransform {
  transform(value: string, format: string = 'medium'): string {
    if (!value || !value.includes(',')) return '';

    const [y, m, d] = value.split(',').map(Number);
    const date = new Date(y, m - 1, d);

    return new Intl.DateTimeFormat('fr-FR').format(date);
  }
}

import { Component, CUSTOM_ELEMENTS_SCHEMA, inject, OnDestroy, OnInit } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
