import { Component, CUSTOM_ELEMENTS_SCHEMA, inject, OnDestroy, OnInit } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { Subject, Observable, takeUntil } from 'rxjs';
import { Theme } from 'src/app/core/models/theme.interface';
import { User } from 'src/app/core/models/user.interface';
import { SessionService } from 'src/app/core/services/session.service';
import { SubscriptionService } from 'src/app/core/services/subscription.service';
import { UserService } from 'src/app/core/services/user.service';
import { mePassValidator } from 'src/app/core/validators/valid.validator';
import { MaterialModule } from 'src/app/shared/material.module';

@Component({
  selector: 'app-me',
  templateUrl: './me.component.html',
  styleUrl: './me.component.scss',
  schemas:[CUSTOM_ELEMENTS_SCHEMA],
  imports:[MaterialModule]
})
export class MeComponent  implements OnInit, OnDestroy{

  private destroy$!: Subject<boolean>;
  public user$!: Observable<User>;
  private sessionService = inject(SessionService);
  private subscriptionService = inject(SubscriptionService);
  private userService = inject(UserService);
  private fb = inject(FormBuilder);
  public userForm: FormGroup | undefined;
  public theme$!: Observable<Theme[]>;

  ngOnInit(): void {
    this.destroy$ = new Subject<boolean>();
    this.userService.getById(this.sessionService.sessionInformation!.id.toString())
        .pipe(takeUntil(this.destroy$))
        .subscribe((user: User) => this.initForm(user));
        
    this.theme$ = this.subscriptionService.getByUser();
  }

  ngOnDestroy(): void {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  submit() {
    const userPayload = this.userForm?.value as User;

    this.userService
      .update(userPayload, this.sessionService.sessionInformation!.id.toString())
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        this.ngOnInit();
      });
  }

  initForm(user: User){
    this.userForm = this.fb.group({
      username: [user.username],
      email: [user.email],
      password: ['',[mePassValidator()]]
    });
  }

  public subscribeTheme(idTheme: number):void{
      this.subscriptionService.unsubscribe(idTheme.toString()).pipe(takeUntil(this.destroy$)).subscribe(_ => this.ngOnInit());
  }
}

import { Component, inject, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { map, Observable } from 'rxjs';
import { Article } from 'src/app/core/models/article.interface';
import { ArticleService } from 'src/app/core/services/article.service';
import { MaterialModule } from 'src/app/shared/material.module';
import { CustomDatePipePipe } from "../../shared/customPipe/custom-date-pipe.pipe";

@Component({
    selector: 'app-article',
    templateUrl: './articles.component.html',
    styleUrls: ['./articles.component.scss'],
  imports: [MaterialModule, CustomDatePipePipe]
})
export class ArticlesComponent implements OnInit {

  private articleService = inject(ArticleService);
  private router = inject(Router);
  public sortIndex: boolean = false;

  public article$: Observable<Article[]> = this.articleService.getSubscribed();
  
  ngOnInit(): void {
    this.sort();
  }

  public createArticle():void{
    this.router.navigate(['/article/form']);
  }

  public viewArticleDetail(articleId:number):void{
    this.router.navigate(['/article/detail/', articleId]);
  }

  public sort():void{
      if (this.sortIndex) this.article$ = this.article$.pipe(
        map(article =>
          article.sort(
            (a, b) => Date.parse(a.date.toString()) - Date.parse(b.date.toString())
        )));

      if (!this.sortIndex) this.article$ = this.article$.pipe(
        map(article =>
          article.sort(
            (a, b) => Date.parse(b.date.toString()) - Date.parse(a.date.toString())
        )));
      this.sortIndex = !this.sortIndex;
  }



}

